use vstd::prelude::*;

verus! {
    /// solve takes two signed 8‐bit integers n and m (both ≥ 1)
    /// and returns a pair (first, second) such that:
    ///   second = min(n, m)
    ///   first  = max(n, m) − 1
    /// and therefore first + second = n + m − 1.
    fn solve(n: i8, m: i8) -> (first: i8, second: i8)
        requires
            n >= 1,
            m >= 1,
        ensures
            // second component is the minimum of n and m
            second == if n <= m { n } else { m },
        ensures
            // first component is the maximum of n and m, minus one
            first == if n >= m { n - 1 } else { m - 1 },
        ensures
            // the two outputs sum to n + m - 1 (in mathematical integers)
            (first as int) + (second as int) == (n as int) + (m as int) - 1,
    {
        if n <= m {
            // second = n (the smaller), first = m - 1
            (m - 1, n)
        } else {
            // second = m (the smaller), first = n - 1
            (n - 1, m)
        }
    }
}

